//! Cover art test support: seeded library artwork and fixture catalog
//! instances.
//!
//! The browse fixtures seed rows whose files do not exist, because their tests
//! only read metadata. A cover art test has to serve actual bytes, so
//! [`seed_album`] writes real audio generated by the test-support crate - one
//! track per [`Art`], each with an embedded picture, a sidecar image, or nothing
//! - and inserts the matching library rows.
//!
//! The catalog side of a cover art test needs an instance pointed at a local
//! server, which is what [`Fixture::install_catalog_instance`] and
//! [`Fixture::assign_layer`] configure: `coverUrl`-style settings carry the
//! mock server's URL, and the instance's manifest allows exactly that host.

#![allow(dead_code)]

use std::path::{Path, PathBuf};

use hearthsound_core::{Availability, EntityId, Layer};
use hearthsound_library::{
    AlbumInput, ArtistCredit, LibraryRepository, Origin, ScannedMediaFile, TrackInput,
};
use hearthsound_plugin_host::{InstanceService, InstanceSpec, PluginSource};
use hearthsound_test_support::audio::{AudioFixture, AudioFormat, TrackTags};
use hearthsound_test_support::fixture_plugin;
use serde_json::Value;

use super::Fixture;

/// The artwork a seeded media file carries.
pub enum Art {
    /// An embedded PNG cover of the given size and colour.
    Embedded {
        /// The width and height in pixels.
        size: u32,
        /// The colour as 24-bit RGB.
        rgb: u32,
    },
    /// No embedded art, with these bytes written as `cover.jpg` beside the
    /// file, which is what a sidecar image is.
    Sidecar(Vec<u8>),
    /// No art at all.
    None,
}

/// One seeded album and its generated files.
pub struct Seeded {
    /// The album's credited artist.
    pub artist: EntityId,
    /// The album.
    pub album: EntityId,
    /// The tracks, in playing order.
    pub tracks: Vec<EntityId>,
    /// The files written, aligned with `tracks`.
    pub paths: Vec<PathBuf>,
    /// The bytes of the first embedded cover, when a track has one.
    pub embedded: Option<Vec<u8>>,
}

impl Seeded {
    /// Returns the first track's id.
    ///
    /// # Panics
    ///
    /// Panics when no track was seeded, which is a test's own arrangement
    /// mistake.
    pub fn first_track(&self) -> EntityId {
        self.tracks[0]
    }
}

/// Seeds one album with one generated file per entry of `files`.
///
/// Each file is written into its own library folder under the fixture's
/// temporary directory, tagged, and registered as the track's preferred file.
/// The rows are written through the library crate's own writers, so the tests
/// read exactly what a scan would have produced.
///
/// # Parameters
///
/// - `fixture`: the fixture to seed into.
/// - `title`: the album title, which also names its folder and its artist.
/// - `files`: the artwork each track's file carries, in playing order.
///
/// # Returns
///
/// The seeded album, its artist, and its tracks.
pub async fn seed_album(fixture: &Fixture, title: &str, files: &[Art]) -> Seeded {
    let library = LibraryRepository::new(&fixture.database);
    let root = fixture.subdir(&format!("{title}-folder"));
    let folder = library
        .add_library_folder(&root, Some(fixture.user_id.uuid()))
        .await
        .unwrap();
    let artist_name = format!("{title} Artist");
    let mut album_input = AlbumInput::new(title, Origin::Local);
    album_input.display_artist = Some(artist_name.clone());
    let album = library
        .upsert_album(
            &album_input,
            &[ArtistCredit::new(artist_name.clone(), "main")],
        )
        .await
        .unwrap();
    let artist = library.list_album_artists(album).await.unwrap()[0].id;

    let directory = root.join(title);
    std::fs::create_dir_all(&directory).unwrap();
    let mut tracks = Vec::new();
    let mut paths = Vec::new();
    let mut embedded = None;
    for (index, art) in files.iter().enumerate() {
        let number = index + 1;
        let file_name = format!("{number:02}.mp3");
        let mut audio = AudioFixture::new(AudioFormat::Mp3Cbr)
            .tags(TrackTags::new(
                format!("{title} {number}"),
                artist_name.clone(),
            ))
            .file_name(file_name.clone());
        if let Art::Embedded { size, rgb } = art {
            audio = audio.cover_png(*size, *rgb);
        }
        let path = audio.write_into(&directory).await.unwrap();
        let metadata = std::fs::metadata(&path).unwrap();
        let has_embedded = matches!(art, Art::Embedded { .. });
        if has_embedded {
            let picture = directory.join(format!("{number:02}.cover.png"));
            embedded = Some(std::fs::read(picture).unwrap());
        }
        if let Art::Sidecar(bytes) = art {
            std::fs::write(directory.join("cover.jpg"), bytes).unwrap();
        }

        let mut input = TrackInput::new(
            format!("{title} {number}"),
            Origin::Local,
            Availability::Local,
        );
        input.album_id = Some(album);
        input.display_artist = Some(artist_name.clone());
        input.track_number = Some(number as i64);
        input.disc_number = Some(1);
        input.duration_ms = Some(1_000);
        let track = library
            .insert_track(
                &input,
                &[ArtistCredit::new(artist_name.clone(), "main")],
                &[],
            )
            .await
            .unwrap();
        library
            .upsert_folder_media_file(
                track,
                &ScannedMediaFile {
                    folder_id: folder.id,
                    rel_path: format!("{title}/{file_name}"),
                    size: metadata.len() as i64,
                    mtime_ms: mtime_ms(&metadata),
                    format: Some("mpeg".to_owned()),
                    codec: Some("mp3".to_owned()),
                    bitrate_kbps: Some(320),
                    sample_rate: Some(44_100),
                    bit_depth: None,
                    channels: Some(2),
                    duration_ms: Some(1_000),
                    lossless: Some(false),
                    replaygain: None,
                    has_embedded_art: Some(has_embedded),
                },
            )
            .await
            .unwrap();
        tracks.push(track);
        paths.push(path);
    }

    Seeded {
        artist,
        album,
        tracks,
        paths,
        embedded,
    }
}

impl Fixture {
    /// Installs a fixture catalog plugin and configures one instance of it.
    ///
    /// # Parameters
    ///
    /// - `slug`: the instance slug, which is the one an `x_` id carries.
    /// - `archive`: the fixture archive file name.
    /// - `config`: the instance's server-scoped configuration, which is where a
    ///   test hands the plugin the URL of its mock server.
    pub async fn install_catalog_instance(&self, slug: &str, archive: &str, config: Value) {
        let installed = self.host.install(&fixture_plugin(archive)).await.unwrap();
        let plugin_id = self
            .repository
            .register_installed(&installed, PluginSource::Sideload)
            .await
            .unwrap()
            .id;
        self.instances()
            .create(&InstanceSpec {
                slug: slug.to_owned(),
                plugin_id,
                display_name: format!("{slug} display"),
                server_config: config,
                host_config: Value::Null,
            })
            .await
            .unwrap();
    }

    /// Assigns instances to a layer, in order, and reloads the registry.
    ///
    /// # Parameters
    ///
    /// - `layer`: the layer the instances serve.
    /// - `slugs`: the instance slugs, in the order the layer policy tries them.
    pub async fn assign_layer(&self, layer: Layer, slugs: &[&str]) {
        let slugs: Vec<String> = slugs.iter().map(|slug| (*slug).to_owned()).collect();
        self.instances().set_layer(layer, &slugs).await.unwrap();
        self.registry.rebuild().await.unwrap();
    }

    /// Builds the instance service over the fixture's host, tables and secrets.
    fn instances(&self) -> InstanceService {
        InstanceService::new(
            std::sync::Arc::clone(&self.host),
            self.repository.clone(),
            self.secrets.clone(),
        )
    }
}

/// Lists the file names of a directory, sorted, tolerating a missing directory.
///
/// # Parameters
///
/// - `path`: the directory to list.
///
/// # Returns
///
/// The names, or an empty vector when the directory does not exist, which is
/// what an artwork cache that was never written looks like.
pub fn files_in(path: &Path) -> Vec<String> {
    let mut names: Vec<String> = std::fs::read_dir(path)
        .map(|entries| {
            entries
                .filter_map(|entry| entry.ok())
                .map(|entry| entry.file_name().to_string_lossy().into_owned())
                .collect()
        })
        .unwrap_or_default();
    names.sort();
    names
}

/// Returns a file's modification time in unix milliseconds.
///
/// # Parameters
///
/// - `metadata`: the file's metadata.
///
/// # Returns
///
/// The time, or zero when the platform does not report one.
fn mtime_ms(metadata: &std::fs::Metadata) -> i64 {
    metadata
        .modified()
        .ok()
        .and_then(|time| time.duration_since(std::time::UNIX_EPOCH).ok())
        .map(|duration| duration.as_millis() as i64)
        .unwrap_or(0)
}
